	const second = uint64(time.Second)
	if rest < second {
		switch {
		case rest%uint64(time.Millisecond) == 0:
			return sign + strconv.FormatUint(rest/uint64(time.Millisecond), 10) + "ms"
		case rest%uint64(time.Microsecond) == 0:
			return sign + strconv.FormatUint(rest/uint64(time.Microsecond), 10) + "us"
		}
		return sign + strconv.FormatUint(rest, 10) + "ns"
	}
